import logging
from taf.collectors.ttitrace_4g.factory import (TtiTrace4GCollectorFactorySelector,
                                                TtiTraceServer4GFactorySelector)
from taf.collectors.core import core

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class ttitrace_4g(core):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    _factory = TtiTrace4GCollectorFactorySelector()
    _server_factory = TtiTraceServer4GFactorySelector()

    def create_ttitrace_server_4g(self,
                                  name,
                                  enb_ip=None,
                                  ttitrace_server_path=None,
                                  executor=None):
        """
        Create TtiTraceServer4G which can further be used by TtiTrace4GCollector. It internally runs TTITraceServer.linux
        command in setup and closes command session at teardown.

        :param str name: name of tool
        :param str enb_ip: eNB IP address, default value is '192.168.255.1'
        :param str ttitrace_server_path: (Optional) absolute path of TTITraceServer.linux, default value is
                                         '/opt/TtiTraceServer/TTITraceServer.linux'
        :param dict executor: (Optional) executor parameters for remote execution (e.g. host=10.128.7.1, user=ute, password=Ute),
                              default: local execution

        :return: TtiTraceServer4G : Created object of TtiTraceServer4G

    """
        configuration = {"name": name}
        for parameter_name, parameter_value in locals().items():
            if parameter_name in ["enb_ip",
                                  "ttitrace_server_path",
                                  "executor"] and parameter_value is not None:
                configuration[parameter_name] = parameter_value
        logger.info("Creating Ttitrace_server_4g with alias name :" + name)
        ttitrace_server_4g = self._server_factory.create(configuration=configuration, existing_arguments={})
        logger.info("Ttitrace_server_4g created successfully")
        self.set_alias(name, ttitrace_server_4g)

    def create_ttitrace_4g_collector(self,
                                     name,
                                     tool,
                                     global_cell_id,
                                     ttitrace_client_path=None,
                                     file_name=None,
                                     executor=None):
        """
        Create TtiTrace4GCollector. It internally runs TTITraceStreamingClient.linux command in start and stop. It
        requires created TtiTraceServer4G instance as tool for required TTITraceServer.linux run in background.

        :param str name: name of collector
        :param str tool: alias of previously created TtiTraceServer4G.
        :param int global_cell_id: global cell id configured in eNB for TtiTrace collection
        :param str ttitrace_client_path: (Optional) absolute path of TTITraceStreamingClient.linux, default value is
                                         '/opt/TtiTraceServer/TTITraceStreamingClient/TTITraceStreamingClient.linux'
        :param str file_name: (Optional) identifier string need to be added in collected TTI trace files, default value
                              is 'trace_file'
        :param dict executor: (Optional) executor parameters for remote execution (e.g. host=10.128.7.1, user=ute, password=Ute),
                              default: local execution

        :return: TtiTrace4GCollector : Created object of TtiTrace4GCollector
        """
        configuration = {"name": name,
                         "global_cell_id": int(global_cell_id),
                         "tool": self.get_alias_value(tool)}
        for parameter_name, parameter_value in locals().items():
            if parameter_name in ["ttitrace_client_path", "file_name", "executor"] and parameter_value is not None:
                configuration[parameter_name] = parameter_value
        logger.info("Creating Ttitrace_4g Collector with alias name :" + name)

        ttitrace_4g = self._factory.create(configuration=configuration, existing_arguments={})
        logger.info("Ttitrace_4g Collector created successfully")
        self.set_alias(name, ttitrace_4g)
